def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"], vars["v4"], vars["v5"]]
    minimum = min(values)
    maximum = max(values)
    result = round(maximum - minimum, 3)

    return {
        "value": result,
        "trace": {
            "values": values,
            "minimum": minimum,
            "maximum": maximum,
            "range": result,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "amount"
            }
        }
    }
